function analyticsV2(){analytics();const labels={yesterday:'Yesterday',this_week:'This week',last_week:'Last week',last_30_days:'Last 30 days'},bar=document.createElement('div');bar.className='panel panel-pad';bar.style.marginBottom='18px';bar.innerHTML=`<div class="line-actions">${Object.entries(labels).map(([key,label])=>btn(label,'analytics-range',key===state.analyticsRange?'primary mini':'secondary mini',`data-range="${key}"`)).join('')}</div><p class="sub" style="margin:10px 0 0">Reporting period: <b>${esc(state.workspace.google_metrics?.period||labels[state.analyticsRange])}</b></p>`;$('viewContent').prepend(bar)}
