function overviewV2(){overview();const integrations=state.workspace.integrations||{},connected=['google','meta','tiktok'].filter(provider=>integrations[provider]?.status==='connected'),accountCheck=[...document.querySelectorAll('.check')].find(item=>item.querySelector('b')?.textContent==='Advertising accounts'),emptyNotice=[...document.querySelectorAll('.notice.warning')].find(item=>item.textContent.includes('No live campaign metrics'));if(accountCheck){accountCheck.querySelector('.check-icon').textContent=connected.length?'✓':'○';accountCheck.querySelector('small').textContent=connected.length?`${connected.map(provider=>provider==='google'?'Google Ads':provider==='meta'?'Meta Ads':'TikTok Ads').join(', ')} connected to this workspace.`:'No advertising platform is connected to this workspace.'}if(emptyNotice&&connected.length){emptyNotice.className='notice info';emptyNotice.textContent='Live advertising data is available from the connected platforms. Campaign changes still require explicit confirmation.'}}
function render(){if(!state.workspace)return;({overview:overviewV2,analytics:analyticsV2,seo,business:businessProfile,tracking,campaigns,approvals,assistant,accounts:accountsV3,settings,activity}[state.view]||overviewV2)();document.querySelectorAll('select[name="provider"]').forEach(select=>{if(!select.querySelector('option[value="tiktok"]'))select.insertAdjacentHTML('beforeend','<option value="tiktok">TikTok Ads</option>')})}
async function syncAnalyticsRange(range){if(state.busy)return;try{state.busy=true;state.analyticsRange=range;state.workspace.google_metrics=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google/sync?range=${encodeURIComponent(range)}`,'POST',{});render();toast(`${state.workspace.google_metrics.period} analytics loaded.`)}catch(e){toast(e.message,true)}finally{state.busy=false}}
function updateAssetRequirements(){const provider=$('campaignForm').elements.provider.value,text={google:'Google Search uses headlines and descriptions during the publishing step. Optional images must be public HTTPS URLs.',meta:'Meta requires at least one public HTTPS image or video URL. Recommended starting formats: square/vertical images and short vertical video.',tiktok:'TikTok requires at least one public HTTPS video URL. Use a mobile-first vertical video with clear audio, captions and a strong opening.'}[provider];$('assetRequirements').textContent=text}
async function suggestAudience(){if(state.busy)return;const f=$('campaignForm'),service=f.elements.service.value.trim(),location=f.elements.audience_location.value.trim(),box=$('campaignResearch');if(!service||!location){toast('Add the service and target location before researching.',true);return}const payload={provider:f.elements.provider.value,objective:f.elements.objective.value,service,budget_aed:f.elements.budget_aed.value||'0',audience_location:location,landing_url:f.elements.landing_url.value.trim(),brief:f.elements.brief.value.trim()};try{state.busy=true;box.className='notice info';box.textContent='Researching current platform and business sources…';const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/agent/recommend-campaign`,'POST',payload),r=x.recommendation,e=x.evidence;f.elements.audience_source.value='suggested';f.elements.audience_age_min.value=r.audience_age_min;f.elements.audience_age_max.value=r.audience_age_max;f.elements.audience_gender.value=r.audience_gender;f.elements.audience_interests.value=r.audience_interests.join(', ');f.elements.placements.value=r.placements.join(', ');f.elements.call_to_action.value=r.call_to_action;f.elements.research_payload.value=JSON.stringify({recommendation:r,evidence:e});const list=(title,items)=>items?.length?`<p><b>${esc(title)}:</b> ${items.map(esc).join(' · ')}</p>`:'';box.innerHTML=`<p><b>Research confidence: ${esc(r.confidence)}</b> · ${esc(r.audience_summary)}</p><p class="sub">AI: ${esc(e.ai_provider||'configured provider')} · Research: ${esc(e.research_mode||'source grounded')}</p>${list('Creative angles',r.creative_angles)}${list('Assets to provide',r.asset_requirements)}${list('Missing inputs',r.missing_inputs)}${list('Assumptions',r.assumptions)}${e.sources?.length?`<p><b>Sources:</b> ${e.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>`).join(' · ')}</p>`:''}<p class="sub">Advisory draft only. Review account eligibility and current specifications before publishing.</p>`;toast('Research-backed recommendation added. Review every field.');updateAssetRequirements()}catch(e){box.className='notice warning';box.textContent=e.message;toast(e.message,true)}finally{state.busy=false}}
async function action(act,id){if(state.busy)return;const tid=encodeURIComponent(state.tenant), base=`/api/workspaces/${tid}`;try{state.busy=true;if(act==='logout'){await req('/api/logout','POST',{});showAuth();return}if(act==='new-campaign'){$('campaignForm').reset();$('campaignResearch').className='notice info hidden';$('campaignResearch').textContent='';$('campaignDialog').showModal();return}if(act==='close-dialog'){$('campaignDialog').close();return}if(act==='close-publish'){$('publishDialog').close();return}if(act==='publish-google'){const c=state.workspace.campaigns.find(x=>x.id===id);if(!c)throw Error('Campaign not found');const f=$('publishForm');f.reset();f.elements.campaign_id.value=c.id;f.elements.daily_budget_aed.value=Math.min(Number(c.budget_aed),70).toFixed(2);f.elements.final_url.value=c.landing_url;f.elements.keywords.value=[c.service,`${c.service} Abu Dhabi`,`${c.service} near me`].filter(Boolean).join('\n');f.elements.headlines.value=[c.name.slice(0,30),(c.service||'Be Relax Massage').slice(0,30),'Book Your Massage Today'].join('\n');f.elements.descriptions.value=[(c.copy||'Relax with professional spa treatments and book your appointment today.').slice(0,90),'Professional massage treatments in Abu Dhabi. Book your relaxing visit online.'].join('\n');f.elements.callouts.value='Professional Therapists\nEasy Online Booking\nRelaxing Spa Experience';$('publishDialog').showModal();return}if(act==='go-assistant'||act==='go-campaigns'){state.view=act==='go-assistant'?'assistant':'campaigns';render();return}if(act==='google-connect'){const x=await req(`${base}/integrations/google/start`,'POST',{});window.location.assign(x.authorization_url);return}if(act==='google-sync'){state.workspace.google_metrics=await req(`${base}/integrations/google/sync`,'POST',{});render();toast('Live Google Ads metrics synced.');return}if(act==='google-disconnect'){if(!confirm('Disconnect Google Ads from this workspace?'))return;await req(`${base}/integrations/google/disconnect`,'POST',{});await loadTenant(state.tenant);toast('Google Ads disconnected.');return}if(act==='save-plan'){if(!state.lastAI)return;state.view='campaigns';render();$('campaignForm').reset();for(let k of ['provider','objective','service','budget_aed']){$('campaignForm').elements[k].value=state.lastAI.input[k]}$('campaignForm').elements['name'].value=state.lastAI.input.service+' — campaign';$('campaignForm').elements['brief'].value=state.lastAI.plan.slice(0,6000);$('campaignDialog').showModal();toast('Plan attached. Review ad copy and add an HTTPS booking URL.');return}if(act==='approve'&&!confirm('Approve this campaign plan internally? NO ads will be published.'))return;if(act==='stop'&&!confirm('Stop internal planning and approvals for this spa?'))return;if(act==='archive'&&!confirm('Archive this internal campaign proposal?'))return;let endpoint={submit:'submit',approve:'approve',reject:'reject',archive:'archive'}[act];if(endpoint){await req(`${base}/campaigns/${encodeURIComponent(id)}/${endpoint}`,'POST',{});toast(`Campaign ${endpoint} completed (internal only).`)}else if(act==='stop'||act==='resume'){await req(`${base}/${act==='stop'?'emergency-stop':'resume-automation'}`,'POST',{});toast(act==='stop'?'Emergency stop enabled.':'Supervised planning resumed.')}await loadTenant(state.tenant)}catch(e){toast(e.message,true)}finally{state.busy=false}}
function metaPublishAction(act,id){if(act==='close-meta-publish'){$('metaPublishDialog').close();return}const c=state.workspace.campaigns.find(x=>x.id===id);if(!c){toast('Campaign not found',true);return}const f=$('metaPublishForm'),spec=c.spec||{};f.reset();f.elements.campaign_id.value=c.id;f.elements.daily_budget_aed.value=Math.min(Number(c.budget_aed)/7,70).toFixed(2);f.elements.final_url.value=c.landing_url||'';f.elements.primary_text.value=(c.copy||`Discover ${c.service||'our wellness services'} and book your visit.`).slice(0,2200);f.elements.headline.value=c.name.slice(0,255);f.elements.image_url.value=(spec.image_urls||[])[0]||'';f.elements.call_to_action.value=['BOOK_NOW','LEARN_MORE','CONTACT_US'].includes(spec.call_to_action)?spec.call_to_action:'BOOK_NOW';$('metaPublishDialog').showModal()}
async function googleAccountAction(act){if(act==='close-google-account'){$('googleAccountDialog').close();return}if(state.busy)return;try{state.busy=true;const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google/accounts`);state.googleAccounts=x.accounts||[];const select=$('googleAccountForm').elements.account;select.innerHTML=state.googleAccounts.map((a,i)=>`<option value="${i}">${esc(a.account_name)} · Customer ${esc(a.customer_id)}${a.login_customer_id?` · Manager ${esc(a.login_customer_id)}`:''}</option>`).join('');if(!state.googleAccounts.length)throw Error('No accessible Google Ads customer accounts were found.');$('googleAccountDialog').showModal()}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function googleAction(act,id){if(state.busy)return;const base=`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google`;try{state.busy=true;if(act==='google-conversions-setup'){if(!confirm('Create or verify all three Google Ads conversion goals? Website tags will still need installation.'))return;const x=await req(`${base}/conversions/setup`,'POST',{});await loadTenant(state.tenant);toast(`${x.created} conversion goal${x.created===1?'':'s'} created; all three are configured.`);return}const status=act==='google-campaign-pause'?'PAUSED':'ENABLED';if(!confirm(`${status==='PAUSED'?'Pause':'Enable'} Google Ads campaign ${id}? This changes the live account immediately.`))return;await req(`${base}/campaigns/${encodeURIComponent(id)}/status`,'POST',{status});state.workspace.google_metrics=await req(`${base}/sync`,'POST',{});render();toast(`Live campaign ${status==='PAUSED'?'paused':'enabled'}.`)}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function providerAction(act){if(state.busy)return;const [provider,operation]=act.split('-'),base=`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/${provider}`;try{state.busy=true;if(operation==='connect'){const x=await req(`${base}/start`,'POST',{});window.location.assign(x.authorization_url);return}if(!confirm(`Disconnect ${provider==='meta'?'Meta Ads':'TikTok Ads'} from this workspace?`))return;await req(`${base}/disconnect`,'POST',{});await loadTenant(state.tenant);toast(`${provider==='meta'?'Meta Ads':'TikTok Ads'} disconnected.`)}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function growthAction(act){if(state.busy)return;const base=`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google-growth`;try{state.busy=true;if(act==='growth-connect'){const x=await req(`${base}/start`,'POST',{});window.location.assign(x.authorization_url);return}if(act==='growth-disconnect'){if(!confirm('Disconnect Google Business Profile, Search Console and Analytics from this workspace?'))return;await req(`${base}/disconnect`,'POST',{});await loadTenant(state.tenant);toast('Google growth services disconnected.');return}state.workspace.growth_metrics=await req(`${base}/sync`,'POST',{});render();toast('Google Business Profile, Search Console and Analytics synced.')}catch(e){toast(e.message,true)}finally{state.busy=false}}
async function init(){const q=new URLSearchParams(location.search),requestedView=q.get('view'),views=['overview','analytics','seo','business','tracking','campaigns','approvals','assistant','accounts','settings','activity'];if(q.get('tenant'))state.tenant=q.get('tenant');if(views.includes(requestedView))state.view=requestedView;if(q.has('google')||q.has('meta')||q.has('tiktok'))state.view='accounts';if(q.has('google_growth'))state.view='seo';try{await refresh();autoSyncConnectedData();for(const provider of ['google','google_growth','meta','tiktok'])if(q.has(provider)){const result=q.get(provider),name={google:'Google Ads',google_growth:'Google Growth',meta:'Meta Ads',tiktok:'TikTok Ads'}[provider];toast(result==='connected'?`${name} connected successfully.`:result==='authorized'?(provider==='google'?'Google Ads authorized. Choose the account for this workspace.':`${name} authorized; API access approval is still pending.`):`${name} authorization failed.`,result==='error');history.replaceState({},'',location.pathname);break}}catch(e){showAuth()}}
document.addEventListener('click',ev=>{const feedback=ev.target.closest('button,a,[role="button"]');if(feedback){feedback.classList.remove('tap-feedback');void feedback.offsetWidth;feedback.classList.add('tap-feedback');setTimeout(()=>feedback.classList.remove('tap-feedback'),240)}const themeButton=ev.target.closest('[data-theme-toggle]');if(themeButton){applyProductTheme(document.documentElement.dataset.productTheme==='dark'?'light':'dark');return}const button=ev.target.closest('[data-action],[data-view]');if(!button)return;if(button.dataset.view){state.view=button.dataset.view;setMobileMenu(false);render();return}const act=button.dataset.action;if(act==='toggle-mobile-menu'){setMobileMenu(!document.body.classList.contains('mobile-menu-open'));return}if(act==='close-mobile-menu'){setMobileMenu(false);return}if(act==='copy-tracking-code'){navigator.clipboard.writeText($('trackingSnippet')?.textContent||'').then(()=>toast('Installation tag copied.')).catch(()=>toast('Copy the installation tag manually.',true));return}if(act==='suggest-audience')suggestAudience();else if(act==='analytics-range')syncAnalyticsRange(button.dataset.range);else if(act.startsWith('growth-'))growthAction(act);else if(act==='google-select-account'||act==='close-google-account')googleAccountAction(act);else if(act==='publish-meta'||act==='close-meta-publish')metaPublishAction(act,button.dataset.id);else if(/^((meta|tiktok)-(connect|disconnect))$/.test(act))providerAction(act);else if(act==='google-conversions-setup'||act==='google-campaign-pause'||act==='google-campaign-enable')googleAction(act,button.dataset.id);else action(act,button.dataset.id)});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')setMobileMenu(false)});
$('loginForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,f=new FormData(form);$('loginError').classList.add('hidden');try{await req('/api/login','POST',{email:f.get('email'),password:f.get('password')});form.reset();await refresh();autoSyncConnectedData()}catch(e){$('loginError').textContent=e.message;$('loginError').classList.remove('hidden')}});
