$('campaignForm').elements.provider.addEventListener('change',updateAssetRequirements);
$('newWorkspace').addEventListener('click',async()=>{const name=window.prompt('Name of the new private business workspace:');if(!name||!name.trim())return;try{const t=await req('/api/workspaces','POST',{name:name.trim()});state.tenant=t.id;state.view='overview';await refresh();toast('New business workspace created.')}catch(e){toast(e.message,true)}});
