$('googleAccountForm').addEventListener('submit',async ev=>{ev.preventDefault();const selected=state.googleAccounts[Number(new FormData(ev.currentTarget).get('account'))];if(!selected){toast('Choose a Google Ads account.',true);return}try{await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google/account`,'POST',{customer_id:selected.customer_id,login_customer_id:selected.login_customer_id||''});$('googleAccountDialog').close();await loadTenant(state.tenant);toast(`${selected.account_name} connected to this workspace.`)}catch(e){toast(e.message,true)}});
$('publishForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,f=new FormData(form),lines=name=>String(f.get(name)||'').split(/[\n,]/).map(x=>x.trim()).filter(Boolean),campaignId=f.get('campaign_id');const audience_segments=[...lines('user_interest_ids').map(id=>({kind:'user_interest',id})),...lines('user_list_ids').map(id=>({kind:'user_list',id}))];const payload={version:1,daily_budget_aed:f.get('daily_budget_aed'),final_url:f.get('final_url'),location_ids:lines('location_ids'),language_ids:lines('language_ids'),keywords:lines('keywords'),headlines:lines('headlines'),descriptions:lines('descriptions'),callouts:lines('callouts'),audience_mode:f.get('audience_mode'),audience_segments,phone_number:f.get('phone_number'),phone_country_code:'AE'};if(!confirm('Create this campaign, ad group, keywords, audiences and assets in Google Ads as PAUSED? It will not spend until separately enabled.'))return;try{const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/campaigns/${encodeURIComponent(campaignId)}/publish/google-search`,'POST',payload);form.closest('dialog').close();await loadTenant(state.tenant);toast(`Google Ads campaign ${x.campaign_id||''} created paused.`)}catch(e){toast(e.message,true)}});
$('metaPublishForm').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.currentTarget,f=new FormData(form),list=name=>String(f.get(name)||'').split(/[,\n]/).map(x=>x.trim()).filter(Boolean),campaignId=f.get('campaign_id'),payload={version:1,daily_budget_aed:f.get('daily_budget_aed'),duration_days:Number(f.get('duration_days')),page_id:f.get('page_id'),instagram_actor_id:f.get('instagram_actor_id'),countries:list('countries'),interest_ids:list('interest_ids'),primary_text:f.get('primary_text'),headline:f.get('headline'),image_url:f.get('image_url'),final_url:f.get('final_url'),call_to_action:f.get('call_to_action'),pixel_id:f.get('pixel_id'),conversion_event:f.get('conversion_event')};if(!confirm('Create the Meta campaign, ad set, creative and ad as PAUSED? This writes to the connected Meta ad account but cannot spend yet.'))return;try{const x=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/campaigns/${encodeURIComponent(campaignId)}/publish/meta`,'POST',payload);form.closest('dialog').close();await loadTenant(state.tenant);toast(`Meta campaign ${x.campaign_id||''} created paused.`)}catch(e){toast(e.message,true)}});
document.addEventListener('submit',async ev=>{if(ev.target.id==='sitemapForm'){ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());if(!confirm(`Submit ${data.sitemap_url} to Google Search Console for ${data.site_url}?`))return;try{await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google-growth/sitemaps`,'POST',data);toast('Sitemap submitted to Google Search Console.')}catch(e){toast(e.message,true)}}else if(ev.target.id==='agentForm'){ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target).entries());const out=$('aiOutput');out.textContent='Preparing your strategy…';try{const result=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/agent/plan`,'POST',f);state.lastAI={...result,input:f};render();toast(result.mode.startsWith('Template')?'Template generated — AI not configured.':'AI campaign draft generated.')}catch(e){out.textContent='Unable to generate plan: '+e.message;toast(e.message,true)}}else if(ev.target.id==='settingsForm'){ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());try{await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/settings`,'POST',data);await loadTenant(state.tenant);toast('Policy updated. No provider budgets were changed.')}catch(e){toast(e.message,true)}}else if(ev.target.id==='trackingForm'){ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());try{await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/tracking`,'POST',data);await loadTenant(state.tenant);toast('Pixel and event settings saved for this workspace.')}catch(e){toast(e.message,true)}}else if(ev.target.id==='inviteForm'){ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());try{const result=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/invitations`,'POST',data);window.prompt('Copy this secure invitation link. It expires in 7 days:',result.invite_url);toast('Invitation link created.')}catch(e){toast(e.message,true)}}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='ga4PropertyForm')return;ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());try{state.workspace.growth_metrics=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google-growth/analytics-property`,'POST',data);render();toast('Google Analytics property selected.')}catch(e){toast(e.message,true)}});
document.addEventListener('submit',async ev=>{if(ev.target.id!=='searchConsolePropertyForm')return;ev.preventDefault();const data=Object.fromEntries(new FormData(ev.target).entries());try{state.workspace.growth_metrics=await req(`/api/workspaces/${encodeURIComponent(state.tenant)}/integrations/google-growth/search-console-property`,'POST',data);render();toast('Search Console property selected.')}catch(e){toast(e.message,true)}});
